// 昌泰3年（900）の時点で語れる話だけ（2026-09-30 900年へ）。本は竹取・伊勢（原型）。古今集（905）はまだ無い。後世の書（今昔・江談抄・十訓抄・撰集抄・絵巻）に載る話は「噂」として置く。
