// ---- 主要人物（全員架空。主人は官職だけで呼び、実在の人名を当てない）
// 項目
//  id/name/who/age : 識別子・名前・話し手の種類・年齢
//  model  : どの人物モデルに載せるか（群衆・牛車の従者・市の売り子など。実装時に対応づける）
//  from/home/work/family : 出身・住まい・職場・家族
//  story  : 身の上（地の文。吹き出しには出さず、台詞を書くときの拠り所）
//  recent : 最近見たもの（台詞にも出す。ほかの人物とつながるものを多めに）
//  wants  : 望み
//  day    : 1日の予定 [始, 終, 場所id, していること, 条件]。終が始より小さければ日をまたぐ。
//           条件（marketDay など say と同じ）が付いた行は合うときだけ使い、上から最初に当たった行を採る
//           （藤次は東市の開催日だけ東市へ買い物、それ以外の日は西市へ）
//  lines  : していること別の独り言（近くを通ると出る）
//  intro  : 話しかけるたびに1段ずつ出す身の上話（挨拶→仕事→身の上→最近見たもの→望み）
//  knows  : ほかの人物について話すこと（その人物が近くにいる／話題に出たとき）
//  bind   : {at:地点id, who:[話し手の種類], r:半径}＝その場所にいちばん近い、その種類の人に載せる（index.html heianSpeechCollect）。
