 day:[[5,7.5,"nobles","支度"],[7.5,8.5,"suzaku","供"],[8.5,12,"suzakuGateApron","待つ"],[12,13.5,"eastMarket","買い物","marketDay"],[12,13.5,"westMarket","買い物","offDay"],[13.5,15,"suzakuGateApron","待つ"],[15,16,"suzaku","供"],[16,21,"nobles","邸"],[21,5,"nobles","寝る"]],
 lines:{"支度":["檳榔毛の葉がほつれとる。今日の供は六人そろったか"],"供":["ゆるりと参れ。右大臣さまのお車は急がんものだ","膝が…いや、何でもない"],"待つ":["今日の除目の相談は長引くぞ。わしの見立てではな","待つ極意？ 座る場所を先に決めることだ","この石はわしの席だ。三十年座っとる","膝が冷える。せめて日なたへ移るか","またお戻りが遅い。夕餉の支度が狂うと妻が怒る","どうせ申の刻まではお戻りにならん"],"買い物":["お戻りはまだ先だ。今のうちに頼まれ物を","奥方さまの紅と、厨の塩と、孫の唐菓子…","菊女の店で干物も見ていくか","鼓が鳴る前に門へ戻らんと、首が飛ぶ"],"邸":["今日も一日、ご主人さまの影を歩いた","膝に湯をかけると少しましだ"],"寝る":["…申の刻…まだお戻りにならん…"]},
