// ---- 事件「紅の値」— 900年（昌泰3年）。2026-09-30 下書き 平安京/heian-case-beni.js から取り込み（井内さん「できそうなことがないか考えて」→「３までをやろう」）
// 架空の事件。特定の家・人物の史実を示すものではない。
//
// 仕組み（既存エンジンのまま動く範囲で設計）
//  beni      : 本筋のカウンタ 0=未着手 1=受けた 9=解決
//  bk_*      : 手がかりの断片。順不同で集められるよう、1つずつ別キーにして値は2
//              （heianQuestToast が v===1 を「受けた」と表示するため、断片は2で立てる）
//  breport   : 検非違使への届け出（任意）
//  OR条件は heianQuestCond が未対応なので、同じ選択肢を条件違いで2つ並べる
//
// エンジン側で要る追加（1行）
//  HEIAN_QUEST_NAMES に beni:'紅の値' を足す。bk_* は名前なしで出るので、
