// ---- 1.75（2026-10-03）恋の頼みごと「常夏の文」（koi_himegoto）。Quick の恋愛と身分差_設計の類型B（主家が対立する家どうしの恋）。
//      少将（後宮・左大臣方・忠誠1）→朱雀門前の右大臣方の若い官人→少将。🚫 下書きは「梅の枝に結んで」＝夏の舞台に合わない。夏の花の撫子（常夏）にした。
//      🚫 受け手を紅梅殿（右大臣邸）の前にすると人がいない（邸の前に群衆が出ない・1.74 の調べ）。官人の多い朱雀門前にした。歌は新作（当時の形の五七五七七）
(function(){
const L=window.HEIAN_LINES; if(!L) return;
L.dialogs.push(
{id:'koi-start',char:'shosho',if:'q:koi_himegoto<1',title:'少将',start:'s',nodes:{
 s:{t:'…鉄の童、口は堅い？ ある御方への文を届けてほしいの。表立っては頼めない相手なのよ',c:[['引き受ける','ok'],['相手は誰？','who'],['関わらない','no']]},
 who:{t:'右大臣方の、お若い官人さま。わたくしの局は左の大臣方。…この文が表に出れば、ただでは済まないわ',c:[['引き受ける','ok'],['関わらない','no']]},
 ok:{t:'ありがとう。撫子の花に結んであるの。あの方は朱雀門の前で、退出の刻を待っておられるはず',set:'koi_himegoto=1',c:[['行ってくる','bye']]},
 no:{t:'…そうね。忘れてちょうだい',end:true},
 bye:{t:'くれぐれも、そっとね',end:true}},
 n:'架空。撫子は夏の花で、古名を常夏という（通説）'},
{id:'koi-deliver',who:['官人'],at:'suzakumon',if:'q:koi_himegoto=1',era:'<tojitsu',title:'右大臣方の若い官人',start:'s',nodes:{
 s:{t:'…後宮の少将どのから？ 撫子の花に。かたじけない。この恋、家の争いとは関わりのないものを',c:[['返しを預かる','yes'],['危ういのでは？','warn']]},
 warn:{t:'わかっておる。左と右の大臣方が睨み合うておるのは、この門の前でも同じだ。…だが、こればかりは止められぬ',c:[['返しを預かる','yes']]},
 yes:{t:'返しの歌を書いた。同じ撫子に結んでくれ。…人目のないところで渡してほしい',set:'koi_himegoto=2',c:[['届ける','bye']]},
 bye:{t:'家の垣根が低くなる日を、待っておる',end:true}}},
{id:'koi-done',char:'shosho',if:'q:koi_himegoto=2',title:'少将',start:'s',nodes:{
 s:{t:'返しの歌…！「常夏の 花に結びし 言の葉を 枯らさで待たむ 夏の夕暮れ」…待つ、と',set:'koi_himegoto=9',c:[['よかったね','end'],['この先どうなるの？','next']]},
 next:{t:'わからないわ。家どうしの風向き次第。…でも、待つと言ってくださる方を、わたくしも待ちましょう',end:true},
 end:{t:'このことは、女御さまにも内緒よ',end:true}}}
);
L.say.push(
 {at:'kokyu',who:'女房',if:'q:koi_himegoto>=9',t:'少将さまの局に、撫子が挿してあるのよ。どなたから？'},
 {at:'suzakumon',who:'官人',if:'q:koi_himegoto>=9',t:'退出の刻になると、あやつは後宮の方ばかり見ておる'}
);
})();
