// ---- 1.99 夜の星の蘊蓄（井内さん「夜、星を見ながら天文とか陰陽の人と話すと色々蘊蓄を聞けたら楽しい」・2026-10-06）
// 本体の対話関数 @hoshi が「いま空にある星官」を拾って hoshiLore[名前].t から1つ読む。昼・曇り・雨は hoshiDay から。
// キーは index.html の HEIAN_ASTERISMS（20）と HEIAN_SKY_STARS（16）の n と完全一致。話し手は陰陽寮の人（漢名で語る。和名は後世の記録なので台詞には出さず n で断る）
// 🚫 入れない: 清少納言の「星はすばる」・七夕の樹木飾り（近世）・安倍晴明の逸話。天文密奏・宣明暦・日月食の予報・客星や彗星が不吉の兆しは陰陽寮の職掌に根を持つ話として混ぜる
(function(){
const L=window.HEIAN_LINES; if(!L) return;
L.hoshiDay=['星は昼にもある。日の光に負けて、見えぬだけじゃ','雲の上にも星は回っておる。晴れた夜にまた来なされ','雨では星は読めぬ。星の話は、晴れた夜に','星を見せてほしければ、日が暮れてから来なされ'];
L.hoshiLore={
// ---- 星官（線で結ぶ20）
'北斗':{t:['あれが北斗。天帝の乗る車じゃ。柄の向きで季節が知れる','北斗の柄が東を指せば春、南なら夏。暦の理の一つよ','北斗は天の帝の車、と漢の書にある。北の空でぐるりと回る'],
 n:'史記天官書「斗為帝車」。柄の向きと季節は鶡冠子など漢籍（要確認）'},
'房宿':{t:['房は天駟、天の馬車の星じゃ。東の青龍の腹に当たる','二十八宿とは月の宿り。房は、月が四つ目に泊まる宿よ'],
 n:'房＝天駟は史記天官書。二十八宿は漢籍。和名（そいぼし）は後世の記録'},
'心宿':{t:['心は大火。火のように赤い星じゃ。これが西へ傾けば、暑さも退く','火星が心に留まるのを「熒惑、心を守る」と言う。帝に凶事ありという、重い天変じゃ','そういう天変を天文博士が見つければ、密かに封をして奏上する。口外は許されぬ'],
 n:'大火・七月流火は詩経。熒惑守心は史記天官書・漢書天文志。天文密奏は職員令（陰陽寮・天文博士）。和名（なかごぼし）は後世'},
'尾宿':{t:['尾は龍の尾。九つの星が、鉤のように曲がって並ぶ','尾の九星は九人の子に見立てる。星が離れれば、君臣の不和の兆しとされる'],
 n:'史記天官書「尾為九子」。和名（あしたれぼし）は後世'},
'箕宿':{t:['箕は穀物をふるう籠の形。箕の星は風を好む、と言う','月が箕に宿る夜は風が立つ、と古い書にある。今宵は吹くかのう'],
 n:'「箕星は風を好み、畢星は雨を好む」の類は書経洪範・史記など漢籍（要確認）。和名（みぼし）は後世'},
'斗宿':{t:['斗は南斗、六つの星の柄杓じゃ。北斗は死を、南斗は生を司る、と唐の書にある','人の寿は南斗に、死は北斗に、帳に記される。…そういう話が漢籍にある'],
 n:'搜神記（管輅の話）ほか漢籍。日本での受容は推定。和名（ひきつぼし）は後世'},
'織女':{t:['織女は三つ星。天の川の西の岸で、機を織る娘の星じゃ','七月七日の夜、宮中では織女に針と糸を供え、裁縫の上達を乞う。乞巧奠と言う','織女と河鼓は、年に一度しか会えぬ。それで七夕のまつりがある'],
 n:'乞巧奠は宮中の七夕の行事（奈良時代から）。七夕の歌は万葉集。樹木飾りなど近世の習いは入れない。和名（たなばたつめ）は後世'},
'河鼓':{t:['河鼓は三つ並ぶ星。牽牛とも言う。天の川の東の岸にある','織女と河鼓は、川を挟んで向き合う。渡れるのは七月七日の夜だけじゃ'],
 n:'牽牛を河鼓二に当てるのは漢代以後で、もとは牛宿を指したとも（推定）。和名（ひこぼし）は後世'},
'天津':{t:['天津は天の川の渡し場。舟はそこから出る、と言う','地の川に津があるように、天にも津がある。川の真ん中に立つ五つの星じゃ'],
 n:'漢籍の星官名（天津四＝デネブ）。「天津」が指す範囲は要確認'},
'室宿':{t:['室は営室。天子の離宮の星とされる','室と壁は四角い枠を成す。二つで一つの館の形じゃ'],
 n:'史記天官書「営室」。和名（はついぼし）は後世'},
'壁宿':{t:['壁は東壁。図書の星とされ、書物を蔵する秘府を司る','大学寮や図書寮の者は、壁の星を拝むと学が進む、と言うておる'],
 n:'東壁＝文章・図書（晋書天文志など）。「拝むと学が進む」は創作。和名（なまめぼし）は後世'},
'牛宿':{t:['牛は牛の星。七夕の牽牛は、昔はこの宿の星を言うたと聞く','今は河鼓の星を牽牛と呼ぶが、唐の学者の間でも言い分が分かれる'],
 n:'牽牛の星が牛宿から河鼓へ移ったとする説（推定・要確認）。和名（いなみぼし）は後世'},
// ---- 冬・春の宵の星官
'参宿':{t:['参は、三つ並ぶ星とその四隅じゃ。西の白虎の宿よ','参と心は、一方が出れば一方が沈む。同じ空に並ばぬので、仲違いした兄弟の譬えに言う'],
 n:'左伝昭公元年（閼伯と実沈）。和名（からすき）は後世'},
'弧矢':{t:['弧矢は弓と矢の形。矢の先は天狼を狙うておる','弧矢の星が明るい年は、兵が動く、とも言う'],
 n:'史記天官書（狼・弧）。占辞は要確認'},
'南河':{t:['南河は天の川の南の岸、北河は北の岸。関を守る砦の星じゃ','南河の三は、冬の空でひときわ明るい。北河と向き合うておる'],
 n:'史記天官書「南北河、両戍」'},
'北河':{t:['北河の二つ星は、兄弟のように並ぶ。南河と天の川を挟んで向き合う','冬の宵、南河と北河が並んで昇る。空の砦の門が開いたようじゃ'],
 n:'史記天官書。北河二・三の呼び名は漢籍'},
'井宿':{t:['井は東井。井戸の枠の形で、水を司る星じゃ','日照りの年は、神泉苑の池守も井の星を見上げると聞く'],
 n:'史記天官書「東井為水事」。池守の話は創作。和名（ちちりぼし）は後世'},
'鬼宿':{t:['鬼は輿鬼。亡骸を乗せる車の星で、死と喪を占う','中に見える白い雲を、積尸気と呼ぶ。亡骸の気が積もる所、と読む。気味の悪い名よ'],
 n:'史記天官書「輿鬼」。積尸気は漢籍。和名（たまおのぼし）は後世'},
'軒轅':{t:['軒轅は黄龍の体。后妃の星じゃ。いちばん明るい星が女主に当たる','軒轅に彗星が入れば、后妃に災い、と占う。天文博士はそれも密かに奏上する'],
 n:'史記天官書「軒轅、黄龍体」。占辞は漢籍（要確認）'},
'軫宿':{t:['軫は車の荷台の後ろの横木。二十八宿の最後の宿じゃ','角で始まり、軫で終わる。月は二十七、八夜で一巡して、また角へ戻る'],
 n:'二十八宿の順は漢籍。和名（みつかけぼし）は後世'},
// ---- 名前だけ出す星（16）
'角宿一':{t:['角は二十八宿の始まり。宿とは月の宿りよ。月は毎夜、一つずつ宿に泊まって行く','日や月が欠ける日は、暦生が宣明暦で前もって割り出す。外れれば、寮の恥じゃ'],
 n:'宿＝月の宿り（漢籍）。宣明暦は貞観4年（862）から。日食・月食の予報は暦博士の職掌（職員令）。和名（すぼし）は後世'},
'大角':{t:['大角は天王の廷の星。橙色の大きな星じゃ。角の宿の北にある','春の宵、東の空から大角が昇る。あれが見えれば、夏も近い'],
 n:'史記天官書「大角者、天王帝廷」'},
'貫索':{t:['貫索は牢の星。輪のように並んで、口が少し開いておる','貫索の口が開けば牢の囚人が放たれ、閉じれば獄が満ちる、と占う'],
 n:'史記天官書・晋書天文志（貫索）。占辞は要確認'},
'虚宿':{t:['虚は哭泣の星。弔いや墓のことを占う','「虚」の字は、むなしい、じゃ。星に悪意は無い。字が暗いだけよ'],
 n:'史記天官書（虚＝哭泣・墳墓）。和名（とみてぼし）は後世'},
'危宿':{t:['危は高い棟に登る人の形。屋根や普請を占う星じゃ','危は危うい、の字。高い所の仕事は、この宿の日を避けよ、と言う者もおる'],
 n:'史記天官書（危＝蓋屋）。日の忌みは創作。和名（うみやめぼし）は後世'},
'北落師門':{t:['北落師門。禁軍の陣の北の門、という名じゃ。南の低い空に、ひとつだけ明るい','星の少ない南の空にぽつんと光る。あれが見えれば秋じゃ'],
 n:'史記天官書「北落師門」（羽林軍の軍門）'},
'昴':{t:['昴は西の白虎の宿。小さな星が群れておる。胡の星と言うて、辺境の兵乱や獄のことを占う','目のよい者には六つも七つも見える。数え比べをする者もおる'],
 n:'史記天官書「昴為髦頭、胡星也」。「すばる」は古くからの和語で、「昴」の字を当てたのは後世（要確認）'},
'畢宿五':{t:['畢は雨を好む星。月が畢に懸かれば大雨になる、と詩にある','畢は獣を獲る網の形。長い柄が付いておる。雨の星で、狩りの星でもある'],
 n:'詩経小雅「月離于畢、俾滂沱矣」。和名（あめふりぼし）は後世'},
'五車二':{t:['五車は天帝の五つの車。五角に星が並ぶ','五車が明るい年は穀物が実る、と占う者もおる'],
 n:'史記天官書（五車）。占辞は要確認'},
'天狼':{t:['天狼は空でいちばん明るい星じゃ。侵略の星と言われ、弧矢の矢がこれを狙う','天狼が赤く燃えれば盗賊が起こる、と占う。…本当かどうかは知らん'],
 n:'史記天官書「狼」・楚辞「天狼を射る」（漢籍）'},
'觜宿一':{t:['觜は虎のくちばし。二十八宿でいちばん小さい宿じゃ','参の三つ星のすぐ近く。小さいゆえ、暦生も数え違えやすい'],
 n:'二十八宿は漢籍。和名（とろきぼし）は後世'},
'星宿一':{t:['星は朱雀の頸の星。南の低い空に、赤く一つだけ光る','朱雀大路の名は、南の朱雀に取ったもの。その頸がこの星よ'],
 n:'四神（青龍・白虎・朱雀・玄武）。朱雀大路の名が南の朱雀に取るとするのは通説。和名（ほとほりぼし）は後世'},
'翼宿一':{t:['翼は朱雀の翼。遠くから来る客を司る星と言う','鴻臚館へ使いの来る年は、翼の星を見よ。…と、年寄りの博士は言うた'],
 n:'史記天官書「翼、遠客」。年寄りの博士の言は創作。和名（たすきぼし）は後世'},
'五帝座一':{t:['太微は天帝の朝廷。五帝座は、その中央の座じゃ。地では朝堂院に当たろう','客星や彗星が太微に入るのは、帝の身の異変の兆し。天文博士は見つけ次第、封をして密かに奏上する','客星とは、ふいに現れてまた消える星よ。「客」は、招かぬ客の客じゃ'],
 n:'史記天官書（太微）。天文密奏は職員令（天文博士）。客星・彗星を不吉とする読みは漢籍'},
'帝':{t:['帝は紫微垣の帝の座。地の帝が内裏におわすように、天の帝はここにおわす','紫微垣は天帝の宮城。星は帝を囲んで、ゆっくり回る'],
 n:'史記天官書（紫微宮）。901年の北極に近い明るい星はこちら（本体の星図の注記）'},
'北極星':{t:['論語に「北辰、その所に居て衆星これに共す」とある。帝の座は動かず、星がその周りを巡る','もっとも、よく測れば、動かぬ所は星の上ではなく、星と星のあいだにある'],
 n:'論語為政。極が星の上に無いことは漢籍に見える（900年の日本の寮が知っていたかは推定）。901年のこの星は極から約7°離れる（本体の注記）'}
};
})();
// ---- 1.99 軽い頼まれごと6本（井内さん「軽い頼まれごとなども含め検討して」・ゲーム性の得を目的にしない、どうでもいいけど記憶に残る散歩）
