 {at:'suzakumon',who:'従者',if:'summer',t:'夏は粽が出る。笹の葉の匂いで、暑さを忘れる'},
 {at:'suzakumon',who:'従者',if:'autumn',t:'新米の餅が出たら、待つのも苦にならん'},
 {at:'suzakumon',who:'従者',if:'winter',t:'冬の焼き餅は、懐に入れて帰りたいほどだ'}
