// ---- 街かどの小さな出来事の台詞（2026-10-07 井内さん「あの大木の辻を西、のように会話とつなぐ」）。
// 本体の HEIAN_QUIRKS（CadKit/index.html）の近く（tr m 以内）で、タグ quirk_<id> が付く。景色の話であり、史料の裏付けは無い（推定・架空）
(function(){const L=window.HEIAN_LINES;if(!L)return;
const Q=(at,who,t,o)=>Object.assign({at,who,t,n:'街かどの景色（推定・架空）'},o||{});
L.say.push(
 Q('quirk_keyaki','庶民','あの大きな欅の辻を西へ曲がれば、市へ近い。迷ったら欅を探しなされ'),
 Q('quirk_keyaki','童','この木、登ると見つかって怒られるんだ。でも、てっぺんから朱雀大路が見えるんだぜ'),
 Q('quirk_keyaki','女','夏はこの欅の下が涼しくて、みな立ち話をしていく'),
 Q('quirk_kusu','庶民','右京の楠じゃ。この辺りは空き地が多いが、この木だけは誰も切らん'),
 Q('quirk_kusu','旅人','大きな楠だな。都の西は人が少ないが、これほどの木は左京にも少ない'),
 Q('quirk_muku','庶民','椋の大木の辻じゃ。実の熟れる頃は、鳥と子供で取り合いになる'),
 Q('quirk_ganseki','庶民','この辻の角の岩は、昔からここにある。荷車は皆、岩をよけて曲がる'),
 Q('quirk_ganseki','童','岩の上に登ると、荷車がよく見えるよ'),
 Q('quirk_ishi2','庶民','東京極の岩か。京の東の端を知らせる目印よ、と祖父は言うておった'),
 Q('quirk_inu3','庶民','ここの犬は三匹。いつもここに居って、誰が通るか見ておる'),
 Q('quirk_inu3','女','三匹とも人なつこい。何も持たぬ者にも尾を振るのよ'),
 Q('quirk_neko','女','猫の親子が、毎日この辻を通る。子猫がころころついて歩くのがかわいいの'),
 Q('quirk_neko','童','ねこ！ ちっちゃいのが二匹いるんだ！'),
 Q('quirk_kodomo1','庶民','この辻は子供の遊び場じゃ。荷車が来ると、蜘蛛の子を散らすように逃げる'),
 Q('quirk_kodomo2','庶民','九条の子らは元気がいい。鬼ごっこの声が、日が暮れるまで止まん'),
 Q('quirk_kodomo2','女','暗くなる前に帰りなさいと、毎日言うのに'),
 Q('quirk_tsuri1','釣り人','堀川で釣れるのは小さな鮒ばかり。でも朝のうちは、手ぶらで帰ることはない'),
 Q('quirk_tsuri1','釣り人','しっ。魚が逃げる。…竿を見ておれば、心が凪ぐ'),
 Q('quirk_tsuri2','釣り人','ここは水が澄んでおる。北の方は荷舟が多うて、魚が寄らん'),
 Q('quirk_tsuri2','庶民','あの釣り人、毎朝おる。釣れた日は近所に分けてくれるんじゃ')
);})();

// ---- 売り子に「何が売れている？」と聞いた答え（2026-10-08 井内さん「塩屋の売り子に聞いたら針と糸だって。塩の話をして欲しい」）。
//  対話 seller-call の hot が '@hot'（index.html の heianDialogFn.hot）で、話し相手の店の品（cand.ware）の行を返す。品が札に無い人は '*'。
(function(){const L=window.HEIAN_LINES;if(!L)return;
L.WARE_HOT={
 '絹':['絹だね。女房さまがたの装束に、よう出る','上等の絹は、位のあるお屋敷から先に決まっていくのさ','絹は光にかざすと分かる。目の利く客ほど長居するよ'],
 '糸':['糸だよ。染めた色糸は女房さまのお使いが多い','糸は撚りで値が決まる。細くて切れんのは高いよ','機を織る家は、糸が切れたと言うて走ってくる'],
 '綿':['綿は冬の前に出る。真綿の衣は温いからね','綿は秋の終わりによう売れる。寒くなると客が並ぶ','綿を詰めた衣は温い。そりゃ出るさ'],
 '布':['布だ。布は銭より強い、何にでも取り替えられる','調布の端数を測ってくれと客が言う。ごまかしは効かんよ','布が出るのは月の初め。禄の布を持った官人が来る'],
 '櫛':['櫛だね。黄楊の櫛は髪のとおりがいい。娘さんがよう買う','櫛は贈り物にもなる。旅に出る人が買っていくよ','櫛は割れやすい。壊れたと買い替えに来るのさ'],
 '針':['針だよ。唐渡りは特によう出る','針は小さいが、なくすと家じゅう大騒ぎ。買い足しが多いのさ','針は一度に何本も買う客が多いよ'],
 '紙':['紙は学生がよう買う。大学寮の使いが束で持っていく','紙屋院の紙は上物だが高い。反故紙もよう売れるよ','写経の紙を買いに来る坊さまが多い'],
 '筆':['筆は学生が買う。穂が兎の毛のは安くて人気だ','筆は消耗品さ。よう書く人ほど通ってくる','筆と墨はそろえて買う客が多いよ'],
 '墨':['墨は松煙の黒がよう出る。磨る手間が違うんだ','墨は寺と役所の注文が多い','墨は硬い方が長持ちする。分かる客は硬いのを選ぶ'],
 '薬':['薬だね。腹の薬、熱の薬。冬の前によう出る','薬は典薬寮の方も買いに来る。…効くのは本当さ','薬は急ぎで買うものだ。夜に駆け込む客もいる'],
 '油':['油だよ。灯明の油はいくらあっても足りん','寺の使いが油をまとめて買う。毎月決まって来るのさ','日が短くなると油が出る。夜が長いからね'],
 '米':['米だ。米はいつでも出る。布と取り替えの客も多い','今年の米は値が動く。升で量って売るから、ごまかしはない','米は月の終わりに出る。禄が尽きるころさ'],
 '塩':['塩だよ。夏は塩が足りなくなるから、よう出る','塩は漬物にも魚にも使う。どの家も切らさんのさ','瀬戸の浜の塩は粒が細かい。目の利く客はこれを選ぶ'],
 '干魚':['干物だ。若狭の干物がよう出る。日持ちするからね','干し鮑や鯖の干物が人気さ。酒の肴にもなる','閉めの鼓の前は干物を安くする。夕方に来な'],
 '海藻':['海藻だよ。精進の日の前によう出る','若狭の海藻は水で戻して汁に入れる。冬場に出るのさ','海藻は軽くて運びやすい。旅の人も買っていく'],
 '菓子':['菓子は干し柿や栗、木の実さ。子ども連れによう出る','秋は干し柿が飛ぶように売れる','甘いものは祭りの前に出る'],
 '沓':['沓だ。雨の日は木の沓が出るね','沓は官人さまが買う。位によって決まりがあるのさ','革の沓は高い。庶民はたいがい草鞋さ'],
 '染':['染め物だ。茜の赤と紫草の紫がよう出る','色が褪せんのが売りさ。祭りの前は染めの注文が増える','染め物は日の当たり方で色が違って見える。買う前に外で見ていきな'],
 '香':['香だ。寺の使いと女房さまがよう買う','唐渡りの香はひとつまみで高い。それでも出るのさ','香は焚きしめて衣に移す。風流な方が買うよ'],
 '太刀':['太刀は衛府のお役人が買う。鞘の拵えで値が違う','太刀はそう毎日は売れんよ。売れる日は一本で一日分さ','腕に覚えのある客は、抜いて見たがるのさ'],
 '錦':['錦は西市だけの品さ。位のあるお屋敷の注文が多い','錦は眺める客のほうが多いがね。買う人は一度に決める','唐風の錦は特によう出る…といっても月に数本さ'],
 '綾':['綾は西市だけで扱う品だ。女房さまがたの装束に出る','綾は織りが細かいほど高い。目の利く客が選ぶのさ','綾は祝い事の前によう出る'],
 '鞍':['鞍だよ。西市は馬具ならいちばんだ','鞍も鐙もそろえて買う客が多い。馬部の方も来るよ','鞍は乗り手に合わせて選ぶ。値切る客には売らん'],
 '醤':['醤だね。魚を炙ってかける。台所の使いがよう買う','醤は樽ごとの客もいる。塩とは違う良さがあるのさ','醤は塩と並んでよう出る。漬物にも使うよ'],
 '生魚':['生魚は朝のうちに売り切れる。淀の鯉がよう出る','魚は傷みが早い。昼を過ぎたら値を下げるのさ','鮎の季節は桶がすぐ空になる'],
 '土器':['土器は割れ物。祭りの前によう出るよ','神さまへのお供えに、新しい土器を買う客が多い','土器は使い捨てのことも多い。だから毎月売れるのさ'],
 '*':['ぼちぼちさ。日によって、出るものは変わるね','よう売れるのは、客が欲しい物さ。…当たり前か']};
})();
